const ACLCategoryManager={async getCategoryCommands(category,currentVersion,currentMode,API){try{const result=await API.parseRule(`+@${category}`,currentVersion,currentMode);return result.granted_commands||[];}catch(error){console.error(`Error getting commands for category ${category}:`,error);return[];}},async getCategoryCommandsCached(category,currentVersion,cache,getCategoryCommands){const cacheKey=`${currentVersion}:${category}`;if(cache.has(cacheKey)){return cache.get(cacheKey);}
const commands=await getCategoryCommands(category);cache.set(cacheKey,commands);return commands;},async getCommandsGrantedByCategories(grantedCategories,currentVersion,currentMode,API){if(grantedCategories.size===0){return[];}
try{const categoryRule=Array.from(grantedCategories).map(cat=>`+@${cat}`).join(' ');const response=await API.parseRule(categoryRule,currentVersion,currentMode);if(response&&response.grouped_commands){const commands=new Set();Object.values(response.grouped_commands).forEach(categoryCommands=>{categoryCommands.forEach(cmd=>commands.add(cmd));});return Array.from(commands);}}catch(error){console.error('Error getting commands for categories:',error);}
return[];},async grantCategoryAndRemoveConflictingCommands(state,category,getCategoryCommandsCached,updateRuleText,scheduleRender,ACLStateManager){try{const categoryCommands=await getCategoryCommandsCached(category);if(!categoryCommands||categoryCommands.length===0){console.warn(`No commands found for category ${category}`);return;}
const conflictingCommands=categoryCommands.filter(cmd=>state.grantedCommands.has(cmd));state.blockedCategories.delete(category);conflictingCommands.forEach(cmd=>{state.grantedCommands.delete(cmd);});state.grantedCategories.add(category);state.orderedTerms=state.orderedTerms.filter(term=>!(term.type==='category'&&term.operation==='block'&&term.value===category)&&!(term.type==='command'&&term.operation==='grant'&&conflictingCommands.includes(term.value)));ACLStateManager.addTerm(state.orderedTerms,'category','grant',category);state.shouldComprehensiveOptimize=true;await updateRuleText();scheduleRender();import('../core/utils.js').then(({default:Utils})=>{Utils.showNotification(`Granted @${category} and removed ${conflictingCommands.length} conflicting command grants`,'success');});}catch(error){console.error(`Error granting category ${category} and removing conflicts:`,error);}},async removePartialGrantsFromBlockedCategory(state,category,getCategoryCommandsCached,scheduleRender){try{const categoryCommands=await getCategoryCommandsCached(category);if(!categoryCommands||categoryCommands.length===0){console.warn(`No commands found for category ${category}`);return;}
const grantedCommands=categoryCommands.filter(cmd=>state.grantedCommands.has(cmd));if(grantedCommands.length===0){return;}
grantedCommands.forEach(cmd=>{state.grantedCommands.delete(cmd);});state.orderedTerms=state.orderedTerms.filter(term=>!(term.type==='command'&&term.operation==='grant'&&grantedCommands.includes(term.value)));import('../core/utils.js').then(({default:Utils})=>{Utils.showNotification(`Removed ${grantedCommands.length} individual command grants from blocked @${category}`,'success');});scheduleRender();}catch(error){console.error(`Error removing partial grants from blocked category ${category}:`,error);}},async grantCategoryAndCleanup(state,category,getCategoryCommandsCached,updateRuleText,scheduleRender,grantCategory){try{const categoryCommands=await getCategoryCommandsCached(category);const categoryCommandSet=new Set(categoryCommands);state.grantedCategories.add(category);state.blockedCategories.delete(category);state.orderedTerms=state.orderedTerms.filter(term=>!(term.type==='category'&&term.value===category));const commandsToRemove=[];state.orderedTerms=state.orderedTerms.filter(term=>{if(term.type==='command'&&categoryCommandSet.has(term.value)){commandsToRemove.push(term.value);state.grantedCommands.delete(term.value);state.blockedCommands.delete(term.value);return false;}
return true;});state.orderedTerms.push({type:'category',operation:'grant',value:category});state.shouldComprehensiveOptimize=true;await updateRuleText();scheduleRender();import('../core/utils.js').then(({default:Utils})=>{const commandCount=commandsToRemove.length;if(commandCount>0){Utils.showNotification(`Granted @${category} category and removed ${commandCount} individual command${commandCount > 1 ? 's' : ''}`,'success');}});}catch(error){console.error('Error granting category and cleaning up:',error);await grantCategory(category);}},async removeAllCategoryRelatedTerms(state,category,getCategoryCommandsCached,updateRuleText,scheduleRender){try{const categoryCommands=await getCategoryCommandsCached(category);if(!categoryCommands||categoryCommands.length===0){console.warn(`No commands found for category ${category}`);return;}
state.grantedCategories.delete(category);state.blockedCategories.delete(category);const categoryCommandsSet=new Set(categoryCommands);categoryCommandsSet.forEach(command=>{state.grantedCommands.delete(command);state.blockedCommands.delete(command);});state.orderedTerms=state.orderedTerms.filter(term=>{if(term.type==='category'&&term.value===category){return false;}
if(term.type==='command'&&categoryCommandsSet.has(term.value)){return false;}
return true;});await updateRuleText();scheduleRender();import('../core/utils.js').then(({default:Utils})=>{Utils.showNotification(`Removed all terms related to @${category} category`,'success');});}catch(error){console.error(`Error removing all terms for category ${category}:`,error);}},async blockCommandFromCategory(state,command,finalizeStateChange){state.blockedCommands.add(command);state.grantedCommands.delete(command);state.orderedTerms=state.orderedTerms.filter(term=>!(term.type==='command'&&term.value===command));state.orderedTerms.push({type:'command',operation:'block',value:command});state.shouldComprehensiveOptimize=true;await finalizeStateChange();}};export default ACLCategoryManager;